import (
	"fmt"
	"strings"
	"unicode"
)

func isbn(text string) bool {
	var digits strings.Builder
	for _, c := range text {
		if c == '-' || unicode.IsSpace(c) {
			continue
		}
		if c < '0' || c > '9' {
			return false
		}
		digits.WriteRune(c)
	}
	code := digits.String()
	if len(code) != 13 {
		return false
	}
	sum := 0
	for i := 0; i < len(code); i++ {
		weight := 1
		if i%2 == 1 {
			weight = 3
		}
		sum += int(code[i]-'0') * weight
	}
	return sum%10 == 0
}
func main() {
	for _, code := range []string{"978-0-306-40615-7", "9780306406158", "978030640615", "978 0 306 40615 7"} {
		fmt.Printf("valid=%t\n", isbn(code))
	}
}

package main

import (
	"fmt"
	"strings"
)

func fields(text string) ([]string, error) {
	result := []string{}
	var current strings.Builder
	escaped := false
	for _, c := range text {
		if escaped {
			if c != ';' && c != '\\' {
				return nil, fmt.Errorf("bad escape")
			}
			current.WriteRune(c)
			escaped = false
			continue
		}
		switch c {
		case '\\':
			escaped = true
		case ';':
			result = append(result, current.String())
			current.Reset()
		default:
			current.WriteRune(c)
		}
	}
	if escaped {
		return nil, fmt.Errorf("trailing escape")
	}
	return append(result, current.String()), nil
}
func main() {
	values, err := fields(`a\;b;c\\d;`)
	if err != nil {
		panic(err)
	}
	fmt.Printf("fields=%d\nfirst=%s\nsecond=%s\nempty-last=%t\n", len(values), values[0], values[1], values[2] == "")
	_, err = fields(`bad\x`)
	fmt.Printf("invalid=%t\n", err != nil)
}

package main

import (
	"fmt"
)

type Opening struct {
	Rune   rune
	Offset int
}

func brackets(text string) (int, error) {
	stack := []Opening{}
	pairs := map[rune]rune{')': '(', ']': '[', '}': '{'}
	for offset, c := range text {
		switch c {
		case '(', '[', '{':
			stack = append(stack, Opening{c, offset})
		case ')', ']', '}':
			if len(stack) == 0 || stack[len(stack)-1].Rune != pairs[c] {
				return offset, fmt.Errorf("mismatch")
			}
			stack = stack[:len(stack)-1]
		}
	}
	if len(stack) > 0 {
		return stack[len(stack)-1].Offset, fmt.Errorf("unclosed")
	}
	return -1, nil
}
func main() {
	_, err := brackets("中{a+[b*(c)]}")
	fmt.Printf("nested-valid=%t\n", err == nil)
	offset, err := brackets("中(a]")
	fmt.Printf("mismatch=%t byte-offset=%d\n", err != nil, offset)
	offset, err = brackets("abc(")
	fmt.Printf("unclosed=%t byte-offset=%d\n", err != nil, offset)
}

package main

import (
	"bytes"
	"fmt"
	"unicode/utf8"
)

type Decoder struct {
	Pending []byte
	Failed  bool
}

func (d *Decoder) Feed(chunk []byte, final bool) (string, error) {
	if d.Failed {
		return "", fmt.Errorf("decoder failed")
	}
	d.Pending = append(d.Pending, chunk...)
	var out bytes.Buffer
	for len(d.Pending) > 0 && utf8.FullRune(d.Pending) {
		r, size := utf8.DecodeRune(d.Pending)
		if r == utf8.RuneError && size == 1 {
			d.Failed = true
			return "", fmt.Errorf("invalid UTF8")
		}
		out.WriteRune(r)
		d.Pending = d.Pending[size:]
	}
	if final && len(d.Pending) > 0 {
		d.Failed = true
		return "", fmt.Errorf("incomplete UTF8")
	}
	return out.String(), nil
}
func main() {
	input := []byte("中😀Go")
	decoder := &Decoder{}
	text := ""
	for i, part := range [][]byte{input[:2], input[2:5], input[5:]} {
		piece, err := decoder.Feed(part, i == 2)
		if err != nil {
			panic(err)
		}
		text += piece
	}
	fmt.Printf("text=%s runes=%d\n", text, utf8.RuneCountInString(text))
	bad := &Decoder{}
	_, err := bad.Feed([]byte{0xff}, true)
	fmt.Printf("invalid=%t\n", err != nil)
	short := &Decoder{}
	_, err = short.Feed([]byte{0xe4, 0xb8}, true)
	fmt.Printf("incomplete=%t\n", err != nil)
}
